import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Ignored Test Inventory and Triage","description":"","frontmatter":{"title":"Ignored Test Inventory and Triage","type":"adr","date":"2026-08-29T00:00:00.000Z","status":"accepted","status_note":"Accepted"},"headers":[],"relativePath":"handl/project/adrs/0038-ignored-test-inventory-and-triage.md","filePath":"vendored/handl/project/adrs/0038-ignored-test-inventory-and-triage.md"}`),a={name:`handl/project/adrs/0038-ignored-test-inventory-and-triage.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0038-ignored-test-inventory-and-triage" tabindex="-1">ADR-0038: Ignored Test Inventory and Triage <a class="header-anchor" href="#adr-0038-ignored-test-inventory-and-triage" aria-label="Permalink to “ADR-0038: Ignored Test Inventory and Triage”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The workspace currently has 34 ignored tests across 10 files in 7 distinct workstreams. These tests were written ahead of their implementing code — they describe expected behavior for features that are stubbed, unwired, or require external infrastructure. The <code>#[ignore]</code> attribute keeps them out of the default <code>cargo test</code> run while preserving them as executable specifications.</p><p>This ADR inventories every ignored test, classifies why it is ignored, and records the decision for each: keep as-is, remove, or un-ignore as part of a named workstream. This prevents ignored tests from becoming invisible dead code and makes the path to green explicit.</p><h2 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to “Inventory”">​</a></h2><h3 id="_1-vm-evaluation-stubbed-11-tests" tabindex="-1">1. VM evaluation stubbed (11 tests) <a class="header-anchor" href="#_1-vm-evaluation-stubbed-11-tests" aria-label="Permalink to “1. VM evaluation stubbed (11 tests)”">​</a></h3><p><strong>Files:</strong></p><ul><li><code>crates/plugin-vm-common/src/middleware_vm.rs</code> (9 tests)</li><li><code>crates/plugin-vm-common/src/host/host_tests.rs</code> (2 tests)</li></ul><p><strong>Reason:</strong> <code>CanonicalVm::eval</code> and <code>CanonicalVm::eval_async</code> in <code>plugin-vm-backend-rust-interpreter</code> return <code>Error::PrimitiveError(&quot;not implemented&quot;)</code>. The tests exercise middleware tracing, async evaluation, and host-bound eval callbacks — all of which require a working tree-walking interpreter.</p><p><strong>Tests:</strong></p><ul><li><code>middleware_records_sync_trace</code></li><li><code>middleware_records_async_trace</code></li><li><code>middleware_trace_summarizes_nested_calls</code></li><li><code>middleware_trace_distinguishes_sync_and_async</code></li><li><code>middleware_trace_records_handler_entry</code></li><li><code>middleware_trace_records_handler_match</code></li><li><code>middleware_trace_records_handler_fallthrough</code></li><li><code>middleware_trace_records_yield_and_resume</code></li><li><code>middleware_trace_summarizes_let_binding</code></li><li><code>host_eval_returns_value</code></li><li><code>host_eval_propagates_error</code></li></ul><h3 id="_2-lsp-plugins-stubbed-6-tests" tabindex="-1">2. LSP plugins stubbed (6 tests) <a class="header-anchor" href="#_2-lsp-plugins-stubbed-6-tests" aria-label="Permalink to “2. LSP plugins stubbed (6 tests)”">​</a></h3><p><strong>File:</strong> <code>crates/tooling/tests/lsp_plugins.rs</code></p><p><strong>Reason:</strong> <code>ToolingHost</code> wires <code>BasicCompletion</code>, <code>BasicGotoDef</code>, and <code>BasicDocumentSymbols</code> as plugins, but the tooling layer does not yet route parsed AST or token spans into the LSP capability handlers. The LSP plugins exist but their <code>run</code> methods return <code>NotImplemented</code>.</p><p><strong>Tests:</strong></p><ul><li><code>complete_includes_let_binding</code></li><li><code>complete_offers_keyword</code></li><li><code>goto_def_finds_let_binding</code></li><li><code>document_symbols_for_let_and_const</code></li><li><code>incremental_change_appends_text</code></li><li><code>format_still_works</code></li></ul><h3 id="_3-format-and-diagnostics-not-implemented-4-tests" tabindex="-1">3. Format and diagnostics not implemented (4 tests) <a class="header-anchor" href="#_3-format-and-diagnostics-not-implemented-4-tests" aria-label="Permalink to “3. Format and diagnostics not implemented (4 tests)”">​</a></h3><p><strong>File:</strong> <code>crates/tooling/tests/perf.rs</code></p><p><strong>Reason:</strong> <code>ToolingHost::format</code> and <code>ToolingHost::diagnose</code> are stubbed. The formatter pipeline (<code>BasicFormatter</code> + <code>FormatBehavior</code> rules) exists in <code>plugin-ext-fmt</code> and <code>kit-canonical</code> registers it, but <code>ToolingHost</code> does not yet invoke the <code>format</code> capability. Similarly, the diagnostics/lint pipeline (<code>BasicLinter</code> + <code>LintBehavior</code>) is registered but not called by the tooling layer.</p><p><strong>Tests:</strong></p><ul><li><code>format_long_pipe_100</code></li><li><code>format_long_pipe_1000</code></li><li><code>format_long_pipe_10000</code> (also notes a debug-build stack overflow for 10k nested pipes)</li><li><code>lsp_diagnostics_long_500</code></li></ul><h3 id="_4-network-tls-integration-5-tests" tabindex="-1">4. Network/TLS integration (5 tests) <a class="header-anchor" href="#_4-network-tls-integration-5-tests" aria-label="Permalink to “4. Network/TLS integration (5 tests)”">​</a></h3><p><strong>Files:</strong></p><ul><li><code>crates/plugin-lib-ws-rfc-native/src/module.rs</code> (3 tests)</li><li><code>crates/plugin-lib-tls-native/src/tests.rs</code> (2 tests)</li></ul><p><strong>Reason:</strong> These tests require either a live TLS handshake against a remote server or a configured <code>rustls</code> crypto provider. The workspace does not bundle a default crypto provider, and CI does not provision TLS certificates. These are integration tests that belong behind a feature flag or a CI-only runner, not in the default test suite.</p><p><strong>Tests:</strong></p><ul><li>WebSocket TLS connect, send, and close (3 tests in <code>module.rs</code>)</li><li>TLS connector tests (2 tests in <code>tests.rs</code>)</li></ul><h3 id="_5-concurrent-stress-tests-5-tests" tabindex="-1">5. Concurrent stress tests (5 tests) <a class="header-anchor" href="#_5-concurrent-stress-tests-5-tests" aria-label="Permalink to “5. Concurrent stress tests (5 tests)”">​</a></h3><p><strong>Files:</strong></p><ul><li><code>crates/plugin-lib-concurrent/tests/stress.rs</code> (4 tests)</li><li><code>crates/plugin-lib-concurrent/src/scheduler.rs</code> (1 test)</li></ul><p><strong>Reason:</strong> High-contention stress tests that spawn many threads and assert scheduling fairness. They are flaky under load and one has a known race condition in the thread pool scheduler. These are not unit tests — they are performance/fairness regressions that require controlled environments.</p><p><strong>Tests:</strong></p><ul><li>4 stress tests in <code>stress.rs</code> (no explicit reason string)</li><li>1 scheduler test (<code>flaky race; see thread pool scheduler</code>)</li></ul><h3 id="_6-http-server-function-value-handlers-not-wired-2-tests" tabindex="-1">6. HTTP server function-value handlers not wired (2 tests) <a class="header-anchor" href="#_6-http-server-function-value-handlers-not-wired-2-tests" aria-label="Permalink to “6. HTTP server function-value handlers not wired (2 tests)”">​</a></h3><p><strong>File:</strong> <code>crates/plugin-lib-http-server-std/tests/integration_tests.rs</code></p><p><strong>Reason:</strong> <code>StdHttpServer::route_function</code> accepts a <code>FunctionValue</code> (with params, body, and patterns) but the server does not yet evaluate the function body through the VM. The handler stores the function but returns <code>NotImplemented</code> on request. Wiring requires the VM eval pipeline (workstream 1) to be functional.</p><p><strong>Tests:</strong></p><ul><li><code>function_value_handler_returns_string</code></li><li><code>function_value_handler_uses_path_param</code></li></ul><h3 id="_7-loader-cli-wiring-not-implemented-1-test" tabindex="-1">7. Loader/CLI wiring not implemented (1 test) <a class="header-anchor" href="#_7-loader-cli-wiring-not-implemented-1-test" aria-label="Permalink to “7. Loader/CLI wiring not implemented (1 test)”">​</a></h3><p><strong>File:</strong> <code>crates/tooling/tests/loader.rs</code></p><p><strong>Reason:</strong> The test loads a native cdylib plugin through <code>NativeLoader</code> and dispatches an <code>echo</code> capability. The <code>NativeLoader</code> plugin exists and the test logic is correct, but <code>ToolingHost</code> does not yet expose a <code>load</code> capability entry point that the CLI can call. The test is a full integration test that requires a compiled cdylib in <code>target/debug</code>.</p><p><strong>Test:</strong></p><ul><li><code>tooling_host_loads_native_plugin_and_dispatches_command</code></li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="keep-all-34-ignored-tests" tabindex="-1">Keep all 34 ignored tests <a class="header-anchor" href="#keep-all-34-ignored-tests" aria-label="Permalink to “Keep all 34 ignored tests”">​</a></h3><p>None of the ignored tests are removed. Each test is an executable specification for a planned feature. Removing them would lose the contract and force re-derivation of the expected behavior when the feature is implemented.</p><h3 id="classify-by-resolution-path" tabindex="-1">Classify by resolution path <a class="header-anchor" href="#classify-by-resolution-path" aria-label="Permalink to “Classify by resolution path”">​</a></h3><p>Each workstream has a clear unblock condition:</p><table tabindex="0"><thead><tr><th>#</th><th>Workstream</th><th>Tests</th><th>Unblock condition</th><th>Depends on</th></tr></thead><tbody><tr><td>1</td><td>VM eval</td><td>11</td><td>Implement <code>CanonicalVm::eval</code> tree-walking interpreter</td><td>—</td></tr><tr><td>2</td><td>LSP plugins</td><td>6</td><td>Wire <code>ToolingHost</code> to invoke LSP capabilities with parsed AST</td><td>Parser (done)</td></tr><tr><td>3</td><td>Format/diagnostics</td><td>4</td><td>Wire <code>ToolingHost::format</code> and <code>diagnose</code> to invoke platform capabilities</td><td>Formatter (done), Linter (done)</td></tr><tr><td>4</td><td>Network/TLS</td><td>5</td><td>Add <code>tls</code> feature flag or move to CI-only suite</td><td>—</td></tr><tr><td>5</td><td>Concurrent stress</td><td>5</td><td>Fix scheduler race; gate behind <code>stress</code> feature flag</td><td>—</td></tr><tr><td>6</td><td>HTTP server function values</td><td>2</td><td>Wire <code>route_function</code> to VM eval pipeline</td><td>Workstream 1</td></tr><tr><td>7</td><td>Loader/CLI</td><td>1</td><td>Expose <code>load</code> capability through <code>ToolingHost</code></td><td>—</td></tr></tbody></table><h3 id="priority-order-for-un-ignoring" tabindex="-1">Priority order for un-ignoring <a class="header-anchor" href="#priority-order-for-un-ignoring" aria-label="Permalink to “Priority order for un-ignoring”">​</a></h3><ol><li><p><strong>Workstream 3 (format/diagnostics)</strong> — the formatter and linter pipelines are already implemented and registered in <code>kit-canonical</code>. The only missing piece is <code>ToolingHost</code> calling the <code>format</code> and <code>lint</code> capabilities. This is the lowest-effort, highest-value unblock.</p></li><li><p><strong>Workstream 2 (LSP plugins)</strong> — the LSP plugins are implemented and registered. <code>ToolingHost</code> needs to parse the source, then invoke <code>completion</code>, <code>goto-def</code>, and <code>document-symbols</code> capabilities with the AST and position. Depends on the parser, which is complete.</p></li><li><p><strong>Workstream 1 (VM eval)</strong> — the largest workstream. Unblocks workstream 6 as a side effect. Requires implementing the tree-walking interpreter in <code>plugin-vm-backend-rust-interpreter</code>.</p></li><li><p><strong>Workstream 7 (loader/CLI)</strong> — small effort once <code>ToolingHost</code> exposes a <code>load</code> entry point.</p></li><li><p><strong>Workstream 4 (network/TLS)</strong> — move behind a <code>tls</code> feature flag so they don&#39;t run by default. No implementation work needed, just gating.</p></li><li><p><strong>Workstream 5 (concurrent stress)</strong> — gate behind a <code>stress</code> feature flag. Fix the scheduler race separately.</p></li><li><p><strong>Workstream 6 (HTTP server function values)</strong> — unblocked once workstream 1 is done.</p></li></ol><h3 id="no-feature-flags-for-workstreams-1–3-and-7" tabindex="-1">No feature flags for workstreams 1–3 and 7 <a class="header-anchor" href="#no-feature-flags-for-workstreams-1–3-and-7" aria-label="Permalink to “No feature flags for workstreams 1–3 and 7”">​</a></h3><p>Workstreams 1, 2, 3, and 7 are core platform features. Their tests should run by default once un-ignored. No feature flag is needed.</p><h3 id="feature-flags-for-workstreams-4-and-5" tabindex="-1">Feature flags for workstreams 4 and 5 <a class="header-anchor" href="#feature-flags-for-workstreams-4-and-5" aria-label="Permalink to “Feature flags for workstreams 4 and 5”">​</a></h3><p>Network/TLS integration tests and concurrent stress tests do not belong in the default <code>cargo test</code> run even when passing. They will be gated behind <code>tls</code> and <code>stress</code> feature flags respectively, and the <code>#[ignore]</code> attribute will be replaced by <code>#[cfg(feature = &quot;...&quot;)]</code>.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>All 34 ignored tests remain in the codebase as executable specifications.</li><li>The unblock condition for each workstream is explicit and tracked in this ADR.</li><li>Workstreams 4 and 5 will eventually move from <code>#[ignore]</code> to <code>#[cfg(feature)]</code>.</li><li>Workstreams 1, 2, 3, 6, and 7 will have <code>#[ignore]</code> removed when their unblock condition is met.</li><li>This ADR should be updated when a workstream is unblocked, recording the commit that un-ignored the tests.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>ADR-0024: Parser Common (Pratt parser architecture — now migrated to <code>ParserBehavior</code>)</li><li>ADR-0027: VM Crate Restructure (CanonicalVm structure)</li><li>ADR-0029: CLI as Capability Orchestrator (loader/CLI wiring)</li><li>ADR-0031: Platform Abstractions (formatter, linter, LSP plugin model)</li><li>ADR-0036: Host Applier as Plugin (ToolingHost context)</li><li>ADR-0037: Plugin Resolution and Excludes</li></ul>`,59)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};